<template>
  <section class="assurance-page">
    <header class="hero">
      <div>
        <p class="eyebrow">Supply chain assurance</p>
        <h1>Supplier due diligence</h1>
        <p class="hero-copy">Assess third-party cybersecurity risk, connect evidence, and maintain an audit-ready record for CRA Article 13.</p>
      </div>
      <AppButton v-if="canWrite" variant="primary" @click="openSupplierCreate">
        <span aria-hidden="true">＋</span> Add supplier
      </AppButton>
    </header>

    <div class="metrics" aria-label="Supplier assurance summary">
      <div class="metric"><span class="metric-icon supplier-icon">S</span><div><strong>{{ suppliers.length }}</strong><span>Suppliers</span></div></div>
      <div class="metric"><span class="metric-icon component-icon">C</span><div><strong>{{ components.length }}</strong><span>Components</span></div></div>
      <div class="metric"><span class="metric-icon review-icon">R</span><div><strong>{{ assessmentsInReview }}</strong><span>Awaiting review</span></div></div>
      <div class="metric"><span class="metric-icon risk-icon">!</span><div><strong>{{ highRiskCount }}</strong><span>High-risk assessments</span></div></div>
    </div>

    <div class="workspace">
      <aside class="supplier-panel">
        <div class="panel-heading">
          <div><h2>Suppliers</h2><span>{{ filteredSuppliers.length }} in register</span></div>
        </div>
        <label class="search-box">
          <svg viewBox="0 0 20 20" aria-hidden="true"><circle cx="9" cy="9" r="5.5"/><path d="m13 13 4 4"/></svg>
          <input v-model="search" type="search" placeholder="Search suppliers" aria-label="Search suppliers">
        </label>
        <div v-if="isLoading" class="panel-state">Loading supplier register…</div>
        <div v-else-if="filteredSuppliers.length === 0" class="panel-state">No suppliers match your search.</div>
        <div v-else class="supplier-list">
          <button v-for="item in filteredSuppliers" :key="item.id" class="supplier-row" :class="{selected:item.id===selectedSupplierId}" @click="selectedSupplierId=item.id">
            <span class="supplier-avatar">{{ initials(item.name) }}</span>
            <span class="supplier-copy"><strong>{{ item.name }}</strong><small>{{ supplierTypeLabel(item.supplier_type) }}</small></span>
            <span class="status-dot" :class="`status-${item.status}`" :title="item.status" />
            <svg class="chevron" viewBox="0 0 16 16" aria-hidden="true"><path d="m6 3 5 5-5 5"/></svg>
          </button>
        </div>
      </aside>

      <main class="detail-panel">
        <div v-if="!selectedSupplier" class="empty-detail">
          <div class="empty-symbol">S</div><h2>Select a supplier</h2><p>Choose a supplier to review its components and due-diligence history.</p>
        </div>
        <template v-else>
          <div class="supplier-header">
            <div class="identity">
              <span class="large-avatar">{{ initials(selectedSupplier.name) }}</span>
              <div><div class="title-line"><h2>{{ selectedSupplier.name }}</h2><StatusBadge :label="selectedSupplier.status" :variant="statusVariant(selectedSupplier.status)" /></div><p>{{ supplierTypeLabel(selectedSupplier.supplier_type) }}<template v-if="selectedSupplier.country_code"> · {{ selectedSupplier.country_code }}</template></p></div>
            </div>
            <AppButton v-if="canWrite" variant="secondary" @click="openSupplierEdit(selectedSupplier)">Edit supplier</AppButton>
          </div>

          <div class="contact-strip">
            <div><span>Security contact</span><a v-if="selectedSupplier.security_contact" :href="`mailto:${selectedSupplier.security_contact}`">{{ selectedSupplier.security_contact }}</a><strong v-else>Not provided</strong></div>
            <div><span>Website</span><a v-if="selectedSupplier.website" :href="selectedSupplier.website" target="_blank" rel="noopener">Open website ↗</a><strong v-else>Not provided</strong></div>
            <div><span>Registered</span><strong>{{ formatDate(selectedSupplier.created_at) }}</strong></div>
          </div>

          <nav class="tabs" aria-label="Supplier sections">
            <button :class="{active:activeTab==='components'}" @click="activeTab='components'">Components <span>{{ selectedComponents.length }}</span></button>
            <button :class="{active:activeTab==='assessments'}" @click="activeTab='assessments'">Assessments <span>{{ selectedAssessments.length }}</span></button>
            <button :class="{active:activeTab==='traceability'}" @click="activeTab='traceability'">Products <span>{{ selectedTraceability.length }}</span></button>
            <button :class="{active:activeTab==='notifications'}" @click="activeTab='notifications'">Notifications <span>{{ selectedNotifications.length }}</span></button>
            <button :class="{active:activeTab==='profile'}" @click="activeTab='profile'">Profile</button>
          </nav>

          <section v-if="activeTab==='components'" class="section-content">
            <div class="section-heading"><div><h3>Third-party components</h3><p>Software, firmware, hardware, and services supplied to your products.</p></div><div class="heading-actions"><AppButton v-if="canWrite" variant="secondary" size="sm" @click="sbomModal=true">Match SBOM</AppButton><AppButton v-if="canWrite" variant="primary" size="sm" @click="openComponentCreate">Add component</AppButton></div></div>
            <div v-if="matchResult" class="result-banner"><strong>{{ matchResult.linked }} new link{{ matchResult.linked===1?'':'s' }}</strong><span>{{ matchResult.matched }} components matched · {{ matchResult.unmatched.length }} need review</span></div>
            <div v-if="selectedComponents.length===0" class="empty-table"><div>◇</div><strong>No components registered</strong><p>Add the first component supplied or maintained by this organisation.</p></div>
            <div v-else class="table-wrap"><table><thead><tr><th>Component</th><th>Type</th><th>Identifier</th><th>Support ends</th><th aria-label="Actions" /></tr></thead><tbody><tr v-for="item in selectedComponents" :key="item.id"><td><RouterLink :to="{name:'third-party-component-detail',params:{componentId:item.id}}" class="component-link">{{ item.name }}</RouterLink><small>{{ item.version || "Version not specified" }}</small></td><td><span class="type-chip">{{ item.component_type }}</span></td><td class="identifier">{{ item.purl || item.cpe || item.part_number || "—" }}</td><td>{{ item.support_end_date || "—" }}</td><td><div class="row-actions"><AppButton v-if="canWrite" variant="ghost" size="sm" @click="openLinkCreate(item.id)">Link product</AppButton><AppButton v-if="canWrite" variant="ghost" size="sm" @click="openComponentEdit(item)">Edit</AppButton></div></td></tr></tbody></table></div>
          </section>

          <section v-else-if="activeTab==='assessments'" class="section-content">
            <div class="section-heading"><div><h3>Due-diligence assessments</h3><p>Versioned decisions, evidence status, and review outcomes.</p></div><AppButton v-if="canWrite" variant="primary" size="sm" @click="assessmentModal=true">New assessment</AppButton></div>
            <div v-if="selectedAssessments.length===0" class="empty-table"><div>✓</div><strong>No assessments yet</strong><p>Create a proportionate CRA due-diligence assessment for this supplier.</p></div>
            <div v-else class="assessment-list"><RouterLink v-for="item in selectedAssessments" :key="item.id" :to="{name:'supplier-assessment-detail',params:{assessmentId:item.id}}" class="assessment-row" :class="{'needs-review':item.reassessment_required}"><span class="assessment-mark" :class="`tier-${item.assessment_tier}`">{{ item.assessment_tier.charAt(0).toUpperCase() }}</span><span class="assessment-copy"><strong>{{ item.title }}</strong><small v-if="item.reassessment_required" class="review-copy">Reassessment due {{ item.reassessment_due_date || 'soon' }} · {{ item.reassessment_reason }}</small><small v-else>Version {{ item.system_version }} · {{ item.responses.length }} responses · {{ item.evidence_links.length }} evidence items</small></span><StatusBadge :label="item.reassessment_required?'Reassess':statusLabel(item.status)" :variant="item.reassessment_required?'warning':assessmentVariant(item.status)" /><svg viewBox="0 0 16 16"><path d="m6 3 5 5-5 5"/></svg></RouterLink></div>
          </section>

          <section v-else-if="activeTab==='traceability'" class="section-content">
            <div class="section-heading"><div><h3>Product traceability</h3><p>Every product release using a component from this supplier, with its SBOM and current assurance state.</p></div><AppButton v-if="canWrite&&selectedComponents.length" variant="primary" size="sm" @click="openLinkCreate()">Link product</AppButton></div>
            <div v-if="selectedTraceability.length===0" class="empty-table"><div>⌁</div><strong>No product links</strong><p>Match an SBOM to connect supplied components to product releases.</p></div>
            <div v-else class="trace-list"><article v-for="row in selectedTraceability" :key="row.id" class="trace-row"><div class="trace-head"><div class="trace-path"><RouterLink :to="{name:'product-detail',params:{productId:row.product_id}}">{{ row.product_name }}</RouterLink><span>›</span><RouterLink :to="{name:'release-gate',params:{releaseId:row.product_release_id}}">{{ row.release_version }}</RouterLink><span>›</span><strong>{{ row.component_name }} {{ row.component_version||'' }}</strong></div><div v-if="canWrite" class="row-actions"><AppButton variant="ghost" size="sm" @click="openLinkEdit(row)">Edit</AppButton><AppButton variant="ghost" size="sm" @click="removeLink(row)">Remove</AppButton></div></div><div class="trace-meta"><span :class="`criticality-${row.criticality}`">{{ row.criticality }} criticality</span><span>{{ row.is_direct?'Direct':'Transitive' }}</span><span v-if="row.is_core_function">Core function</span><span>{{ row.sbom_file_name||'Manually linked' }}</span><RouterLink v-if="row.assessment_id" :to="{name:'supplier-assessment-detail',params:{assessmentId:row.assessment_id}}">{{ row.reassessment_required?'Reassessment required':statusLabel(row.assessment_status||'') }}</RouterLink><span v-else class="gap-text">Assessment missing</span><span v-if="row.maintainer_notification_count">{{ row.maintainer_notification_count }} maintainer notice{{ row.maintainer_notification_count===1?'':'s' }}</span></div><p>{{ row.usage_context||row.criticality_rationale }}</p></article></div>
          </section>

          <section v-else-if="activeTab==='notifications'" class="section-content">
            <div class="section-heading"><div><h3>Maintainer coordination</h3><p>Track vulnerability details and fixes shared with component maintainers.</p></div><AppButton v-if="canWrite&&selectedComponents.length" variant="primary" size="sm" @click="notificationModal=true">New notification</AppButton></div>
            <div v-if="selectedNotifications.length===0" class="empty-table"><div>↗</div><strong>No maintainer notifications</strong><p>Create an auditable record when a vulnerability affects a supplied component.</p></div>
            <div v-else class="table-wrap"><table><thead><tr><th>Component</th><th>Recipient</th><th>Status</th><th>Due</th><th aria-label="Actions" /></tr></thead><tbody><tr v-for="notice in selectedNotifications" :key="notice.id"><td><strong>{{ componentName(notice.component_id) }}</strong><small>{{ notice.notification_method }}</small></td><td>{{ notice.recipient }}</td><td><StatusBadge :label="statusLabel(notice.status)" :variant="notice.status==='acknowledged'||notice.status==='closed'?'success':notice.status==='sent'?'warning':'neutral'" /></td><td>{{ notice.due_date || '—' }}</td><td><AppButton v-if="canWrite&&notice.status==='draft'" variant="ghost" size="sm" @click="setNotificationStatus(notice.id,'sent')">Mark sent</AppButton><AppButton v-else-if="canWrite&&notice.status==='sent'" variant="ghost" size="sm" @click="setNotificationStatus(notice.id,'acknowledged')">Acknowledge</AppButton></td></tr></tbody></table></div>
          </section>

          <section v-else class="section-content profile-section">
            <div><span>Supplier type</span><strong>{{ supplierTypeLabel(selectedSupplier.supplier_type) }}</strong></div><div><span>Country</span><strong>{{ selectedSupplier.country_code || "Not provided" }}</strong></div><div><span>Internal owner</span><strong>{{ selectedSupplier.owner_user_id || "Not assigned" }}</strong></div><div class="notes"><span>Notes</span><p>{{ selectedSupplier.notes || "No notes have been added." }}</p></div>
          </section>
        </template>
      </main>
    </div>
  </section>

  <AppModal v-model="supplierModal" :title="editingSupplierId ? 'Edit supplier' : 'Add supplier'" size="md">
    <form id="supplier-form" class="form-grid" @submit.prevent="saveSupplier"><label class="full"><span>Supplier name</span><input v-model="supplierForm.name" required autofocus></label><label><span>Supplier type</span><select v-model="supplierForm.supplier_type"><option value="commercial">Commercial supplier</option><option value="open_source">Open-source maintainer</option><option value="service_provider">Service provider</option><option value="manufacturer">Manufacturer</option></select></label><label><span>Status</span><select v-model="supplierForm.status"><option value="active">Active</option><option value="inactive">Inactive</option><option value="blocked">Blocked</option></select></label><label><span>Country code</span><input v-model="supplierForm.country_code" maxlength="2" placeholder="e.g. AT"></label><label><span>Security contact</span><input v-model="supplierForm.security_contact" type="email" placeholder="security@example.com"></label><label class="full"><span>Website</span><input v-model="supplierForm.website" type="url" placeholder="https://"></label><label class="full"><span>Notes</span><textarea v-model="supplierForm.notes" rows="3"></textarea></label></form>
    <template #footer><AppButton variant="ghost" @click="supplierModal=false">Cancel</AppButton><AppButton variant="primary" type="submit" form="supplier-form">{{ editingSupplierId ? "Save changes" : "Add supplier" }}</AppButton></template>
  </AppModal>

  <AppModal v-model="componentModal" :title="editingComponentId ? 'Edit component' : 'Add component'" size="lg">
    <form id="component-form" class="form-grid" @submit.prevent="saveComponent"><label class="full"><span>Component name</span><input v-model="componentForm.name" required autofocus></label><label><span>Version</span><input v-model="componentForm.version"></label><label><span>Type</span><select v-model="componentForm.component_type"><option value="software">Software</option><option value="firmware">Firmware</option><option value="hardware">Hardware</option><option value="service">Service</option></select></label><label class="full"><span>Package URL (PURL)</span><input v-model="componentForm.purl" placeholder="pkg:ecosystem/name@version"></label><label><span>CPE</span><input v-model="componentForm.cpe"></label><label><span>Part number</span><input v-model="componentForm.part_number"></label><label><span>Support end date</span><input v-model="componentForm.support_end_date" type="date"></label><label><span>Security update channel</span><input v-model="componentForm.update_channel"></label><label class="full"><span>Notes</span><textarea v-model="componentForm.notes" rows="3"></textarea></label></form>
    <template #footer><AppButton variant="ghost" @click="componentModal=false">Cancel</AppButton><AppButton variant="primary" type="submit" form="component-form">{{ editingComponentId ? "Save changes" : "Add component" }}</AppButton></template>
  </AppModal>

  <AppModal v-model="assessmentModal" title="New due-diligence assessment" size="md"><form id="assessment-form" class="form-grid" @submit.prevent="addAssessment"><label class="full"><span>Assessment title</span><input v-model="assessment.title" required autofocus></label><label><span>Assessment tier</span><select v-model="assessment.assessment_tier"><option value="low">Low</option><option value="medium">Medium</option><option value="high">High</option></select></label><label><span>Scope</span><select v-model="assessment.component_id"><option value="">Supplier-wide</option><option v-for="item in selectedComponents" :key="item.id" :value="item.id">{{ item.name }} {{ item.version }}</option></select></label><label class="full"><span>Tier rationale</span><textarea v-model="assessment.tier_rationale" required rows="3"></textarea></label><label class="full"><span>Methodology</span><textarea v-model="assessment.methodology" required rows="3"></textarea></label></form><template #footer><AppButton variant="ghost" @click="assessmentModal=false">Cancel</AppButton><AppButton variant="primary" type="submit" form="assessment-form">Create draft</AppButton></template></AppModal>
  <AppModal v-model="sbomModal" title="Match an SBOM" size="md"><form id="sbom-form" class="form-grid" @submit.prevent="matchSbom"><label class="full"><span>Software bill of materials</span><select v-model="sbomId" required autofocus><option disabled value="">Select an SBOM</option><option v-for="record in sbomRecords" :key="record.id" :value="record.id">{{ sbomLabel(record) }}</option></select></label><p v-if="!sbomRecords.length" class="form-help full">No SBOM records are available. Add an SBOM from Vulnerability handling first.</p><p v-else class="form-help full">CRANE matches Package URLs first, then exact component name and version. Existing links are preserved.</p></form><template #footer><AppButton variant="ghost" @click="sbomModal=false">Cancel</AppButton><AppButton variant="primary" type="submit" form="sbom-form" :disabled="!sbomId">Review matches</AppButton></template></AppModal>
  <AppModal v-model="linkModal" :title="editingLinkId?'Edit product link':'Link component to product'" size="lg"><form id="link-form" class="form-grid" @submit.prevent="saveLink"><label><span>Component</span><select v-model="linkForm.component_id" required><option disabled value="">Select component</option><option v-for="item in selectedComponents" :key="item.id" :value="item.id">{{ item.name }} {{ item.version||'' }}</option></select></label><label><span>Product release</span><select v-model="linkForm.product_release_id" required><option disabled value="">Select release</option><option v-for="release in releases" :key="release.id" :value="release.id">{{ release.product_name||'Product' }} · {{ release.display_version }}</option></select></label><label><span>Dependency</span><select v-model="linkForm.is_direct"><option :value="true">Direct</option><option :value="false">Transitive</option></select></label><label><span>Criticality</span><select v-model="linkForm.criticality"><option value="low">Low</option><option value="medium">Medium</option><option value="high">High</option></select></label><label class="checkbox-field"><input v-model="linkForm.is_core_function" type="checkbox"><span>Supports a core product function</span></label><label><span>Source SBOM</span><select v-model="linkForm.sbom_record_id"><option value="">Manual link</option><option v-for="record in availableLinkSboms" :key="record.id" :value="record.id">{{ record.file_name||`${record.format.toUpperCase()} SBOM` }}</option></select></label><label class="full"><span>Criticality rationale</span><textarea v-model="linkForm.criticality_rationale" required rows="3" placeholder="Explain the security impact and why this criticality is proportionate."></textarea></label><label class="full"><span>Usage context</span><textarea v-model="linkForm.usage_context" rows="3" placeholder="Describe where and how this component is used in the release."></textarea></label></form><template #footer><AppButton variant="ghost" @click="linkModal=false">Cancel</AppButton><AppButton variant="primary" type="submit" form="link-form">{{ editingLinkId?'Save changes':'Create link' }}</AppButton></template></AppModal>
  <AppModal v-model="notificationModal" title="Notify a component maintainer" size="md"><form id="notification-form" class="form-grid" @submit.prevent="createNotification"><label class="full"><span>Vulnerability report ID</span><input v-model="notification.vulnerability_report_id" required></label><label><span>Component</span><select v-model="notification.component_id" required><option disabled value="">Select component</option><option v-for="item in selectedComponents" :key="item.id" :value="item.id">{{ item.name }} {{ item.version }}</option></select></label><label><span>Method</span><select v-model="notification.notification_method"><option value="email">Email</option><option value="portal">Supplier portal</option><option value="security_advisory">Security advisory</option></select></label><label class="full"><span>Recipient</span><input v-model="notification.recipient" required placeholder="security@supplier.example"></label><label class="full"><span>Information shared</span><textarea v-model="notification.information_shared" required rows="4" placeholder="Describe the vulnerability and remediation information shared."></textarea></label><label><span>Follow-up due</span><input v-model="notification.due_date" type="date"></label></form><template #footer><AppButton variant="ghost" @click="notificationModal=false">Cancel</AppButton><AppButton variant="primary" type="submit" form="notification-form">Create record</AppButton></template></AppModal>
</template>

<script setup lang="ts">
import { computed, onMounted, reactive, ref } from "vue";
import { RouterLink, useRoute } from "vue-router";
import AppButton from "@/components/AppButton.vue";
import AppModal from "@/components/AppModal.vue";
import StatusBadge, { type BadgeVariant } from "@/components/StatusBadge.vue";
import { useAuthStore } from "@/stores/auth";
import { supplierAssessmentService as api } from "@/services/supplier-assessment-service";
import { sbomRecordService } from "@/services/sbom-record-service";
import { productReleaseService } from "@/services/product-release-service";
import type { ComponentTraceability, MaintainerNotification, SbomMatchResult, Supplier, SupplierAssessment, ThirdPartyComponent } from "@/types/supplier-assessment";
import type { SbomRecordRead } from "@/types/product";
import type { ProductReleaseRead } from "@/types/release-gate";

const auth=useAuthStore(), canWrite=computed(()=>auth.hasPermission("supplier_assessment_write"));
const route=useRoute();
const suppliers=ref<Supplier[]>([]),components=ref<ThirdPartyComponent[]>([]),assessments=ref<SupplierAssessment[]>([]),notifications=ref<MaintainerNotification[]>([]);
const traceability=ref<ComponentTraceability[]>([]);
const sbomRecords=ref<SbomRecordRead[]>([]),releases=ref<ProductReleaseRead[]>([]);
const selectedSupplierId=ref(""),search=ref(""),activeTab=ref<"components"|"assessments"|"traceability"|"notifications"|"profile">("components"),isLoading=ref(true);
const supplierModal=ref(false),componentModal=ref(false),assessmentModal=ref(false),sbomModal=ref(false),notificationModal=ref(false),linkModal=ref(false),editingSupplierId=ref(""),editingComponentId=ref(""),editingLinkId=ref("");
const sbomId=ref(""),matchResult=ref<SbomMatchResult|null>(null);
const supplierForm=reactive({name:"",supplier_type:"commercial",status:"active",country_code:"",security_contact:"",website:"",notes:""});
const componentForm=reactive({name:"",version:"",component_type:"software",purl:"",cpe:"",part_number:"",support_end_date:"",update_channel:"",notes:""});
const assessment=reactive({title:"",assessment_tier:"medium",component_id:"",tier_rationale:"",methodology:"CRA Article 13 risk-based supplier due diligence"});
const notification=reactive({vulnerability_report_id:"",component_id:"",recipient:"",notification_method:"email",information_shared:"",due_date:""});
const linkForm=reactive({product_release_id:"",component_id:"",sbom_record_id:"",is_direct:true,is_core_function:false,criticality:"medium",criticality_rationale:"",usage_context:""});
const selectedSupplier=computed(()=>suppliers.value.find(x=>x.id===selectedSupplierId.value));
const selectedComponents=computed(()=>components.value.filter(x=>x.supplier_id===selectedSupplierId.value));
const selectedAssessments=computed(()=>assessments.value.filter(x=>x.supplier_id===selectedSupplierId.value));
const selectedNotifications=computed(()=>notifications.value.filter(x=>selectedComponents.value.some(c=>c.id===x.component_id)));
const selectedTraceability=computed(()=>traceability.value.filter(x=>x.supplier_id===selectedSupplierId.value));
const availableLinkSboms=computed(()=>sbomRecords.value.filter(x=>x.product_release_id===linkForm.product_release_id));
const filteredSuppliers=computed(()=>{const q=search.value.trim().toLowerCase();return q?suppliers.value.filter(x=>`${x.name} ${x.supplier_type} ${x.country_code??""}`.toLowerCase().includes(q)):suppliers.value});
const assessmentsInReview=computed(()=>assessments.value.filter(x=>x.status==="in_review").length);
const highRiskCount=computed(()=>assessments.value.filter(x=>x.assessment_tier==="high"&&!["approved","superseded"].includes(x.status)).length);
async function load(){isLoading.value=true;try{[suppliers.value,components.value,assessments.value,notifications.value,traceability.value,sbomRecords.value,releases.value]=await Promise.all([api.suppliers(),api.components(),api.assessments(),api.notifications(),api.traceability(),sbomRecordService.list(),productReleaseService.list()]);const requested=String(route.query.supplierId||"");if(requested&&suppliers.value.some(x=>x.id===requested))selectedSupplierId.value=requested;else if(!selectedSupplierId.value&&suppliers.value[0])selectedSupplierId.value=suppliers.value[0].id;if(route.query.tab==="traceability")activeTab.value="traceability"}finally{isLoading.value=false}}
function resetSupplier(){Object.assign(supplierForm,{name:"",supplier_type:"commercial",status:"active",country_code:"",security_contact:"",website:"",notes:""})}
function openSupplierCreate(){editingSupplierId.value="";resetSupplier();supplierModal.value=true}
function openSupplierEdit(x:Supplier){editingSupplierId.value=x.id;Object.assign(supplierForm,{name:x.name,supplier_type:x.supplier_type,status:x.status,country_code:x.country_code??"",security_contact:x.security_contact??"",website:x.website??"",notes:x.notes??""});supplierModal.value=true}
async function saveSupplier(){const payload=nullable(supplierForm);const saved=editingSupplierId.value?await api.updateSupplier(editingSupplierId.value,payload):await api.createSupplier(payload);selectedSupplierId.value=saved.id;supplierModal.value=false;await load()}
function resetComponent(){Object.assign(componentForm,{name:"",version:"",component_type:"software",purl:"",cpe:"",part_number:"",support_end_date:"",update_channel:"",notes:""})}
function openComponentCreate(){editingComponentId.value="";resetComponent();componentModal.value=true}
function openComponentEdit(x:ThirdPartyComponent){editingComponentId.value=x.id;Object.assign(componentForm,{name:x.name,version:x.version??"",component_type:x.component_type,purl:x.purl??"",cpe:x.cpe??"",part_number:x.part_number??"",support_end_date:x.support_end_date??"",update_channel:x.update_channel??"",notes:x.notes??""});componentModal.value=true}
async function saveComponent(){const payload=nullable(componentForm);if(editingComponentId.value)await api.updateComponent(editingComponentId.value,payload);else await api.createComponent({...payload,supplier_id:selectedSupplierId.value});componentModal.value=false;await load()}
async function addAssessment(){await api.createAssessment({...assessment,supplier_id:selectedSupplierId.value,component_id:assessment.component_id||null});assessmentModal.value=false;assessment.title="";assessment.tier_rationale="";activeTab.value="assessments";await load()}
async function matchSbom(){matchResult.value=await api.matchSbom(sbomId.value.trim());sbomModal.value=false;sbomId.value="";await load()}
async function createNotification(){await api.createNotification({...notification,due_date:notification.due_date||null});notificationModal.value=false;Object.assign(notification,{vulnerability_report_id:"",component_id:"",recipient:"",notification_method:"email",information_shared:"",due_date:""});await load()}
async function setNotificationStatus(id:string,status:string){await api.updateNotification(id,{status});await load()}
function resetLink(){Object.assign(linkForm,{product_release_id:"",component_id:"",sbom_record_id:"",is_direct:true,is_core_function:false,criticality:"medium",criticality_rationale:"",usage_context:""})}
function openLinkCreate(componentId=""){editingLinkId.value="";resetLink();linkForm.component_id=componentId;linkModal.value=true}
function openLinkEdit(row:ComponentTraceability){editingLinkId.value=row.id;Object.assign(linkForm,{product_release_id:row.product_release_id,component_id:row.component_id,sbom_record_id:row.sbom_record_id||"",is_direct:row.is_direct,is_core_function:row.is_core_function,criticality:row.criticality,criticality_rationale:row.criticality_rationale,usage_context:row.usage_context||""});linkModal.value=true}
async function saveLink(){const payload={...linkForm,sbom_record_id:linkForm.sbom_record_id||null,usage_context:linkForm.usage_context.trim()||null,criticality_rationale:linkForm.criticality_rationale.trim()};if(editingLinkId.value)await api.updateLink(editingLinkId.value,payload);else await api.createLink(payload);linkModal.value=false;activeTab.value="traceability";await load()}
async function removeLink(row:ComponentTraceability){if(!window.confirm(`Remove ${row.component_name} from ${row.product_name} ${row.release_version}?`))return;await api.deleteLink(row.id);await load()}
function componentName(id:string){return components.value.find(x=>x.id===id)?.name??"Unknown component"}
function sbomLabel(record:SbomRecordRead){const release=releases.value.find(x=>x.id===record.product_release_id);const context=release?`${release.product_name||"Product"} · ${release.display_version}`:"Unknown release";return `${context} — ${record.file_name||`${record.format.toUpperCase()} SBOM`} (${record.component_count??record.components_json.length} components)`}
function nullable(value:Record<string,string>){return Object.fromEntries(Object.entries(value).map(([key,item])=>[key,item.trim()||null]))}
function initials(name:string){return name.split(/\s+/).slice(0,2).map(x=>x[0]).join("").toUpperCase()}
function supplierTypeLabel(value:string){return ({commercial:"Commercial supplier",open_source:"Open-source maintainer",service_provider:"Service provider",manufacturer:"Manufacturer"} as Record<string,string>)[value]??value}
function statusLabel(value:string){return value.replaceAll("_"," ").replace(/^./,x=>x.toUpperCase())}
function formatDate(value:string){return new Intl.DateTimeFormat(undefined,{year:"numeric",month:"short",day:"numeric"}).format(new Date(value))}
function statusVariant(value:string):BadgeVariant{return value==="active"?"success":value==="blocked"?"danger":"neutral"}
function assessmentVariant(value:string):BadgeVariant{return value.startsWith("approved")?"success":value==="in_review"?"warning":value==="rejected"?"danger":"neutral"}
onMounted(load);
</script>

